create function pg_temp.ok(v boolean,m text)returns void language plpgsql as $$begin if not coalesce(v,false)then raise exception '%',m;end if;end$$;
create function pg_temp.reject(u uuid,q text,s text)returns void language plpgsql as $$begin perform set_config('request.jwt.claim.sub',u::text,true);begin execute q;raise exception 'permitido';exception when others then if sqlstate<>s then raise;end if;end;end$$;
